import re

from moler.exceptions import ParsingDone, CommandFailure
from ta_moler.cmd.rtg.ws.genericrtgws import GenericRtgWs

__author__ = 'Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2020, Nokia'
__email__ = 'dawid.gwizdz@nokia.com'


class RtgUtil(GenericRtgWs):
    """Command for rtg_util script."""

    def __init__(self, connection, usage, path="/opt/rtg/bin/rtg-util.sh", options=None, prompt=None,
                 newline_chars=None, runner=None):
        """
        Rtg util command.

        :param connection: moler connection to device, terminal when command is executed.
        :param usage: Usage of script. mac|link|rsi|ver|fix|ufix|ovhd|mmi|sshc|rmod|rup|recover|fd1|fd2|getp|check
        :param path: Path to rtg-util script.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(RtgUtil, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.usage = usage
        self.path = path
        self.options = options
        self._parse_functions = {'link': self._parse_link, 'cpu': self._parse_cpu, 'ver': self._parse_ver,
                                 'mmi': self._parse_mmi_output, 'recover': self._parse_recover,
                                 'fd1': self._parse_fpga_registers, 'fd2': self._parse_fpga_registers,
                                 'getp': self._parse_get_parameter}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"{self.path} {self.usage}"
        if self.options:
            cmd = f"{cmd} {self.options}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                if self._parse_functions.get(self.usage):
                    self._parse_functions[self.usage](line)
                else:
                    self._parse_default_output(line)
            except ParsingDone:
                pass
        return super(RtgUtil, self).on_new_line(line, is_full_line)

    # Example line: ERROR: Invalid option: x
    _re_error = re.compile(r'(?P<ERROR>ERROR: .*)')

    def _parse_error(self, line):
        """
        Parse line containing error.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.search(self._re_error, line).group('ERROR')))
            raise ParsingDone

    # Example line: CTRL-01 10.0.2.11       STATUS: OK
    _re_default_output = re.compile(r'(?P<CTRL>CTRL-\d+)\s*(?P<IP>\d+\.\d+\.\d+\.\d+)\s*(\w*:)?\s*(?P<OUT>.*)')
    _key_dict = {'mac': 'MAC', 'rsi': 'RSI_STATUS', 'fix': 'FIX_STATUS', 'ufix': 'UFIX_STATUS',
                 'ovhd': 'OVERHEAD_STATUS', 'sshc': 'COMMAND_OUTPUT', 'check': 'CONNECTION_STATUS'}

    def _parse_default_output(self, line):
        """
        Parse line with default (simple, one value) output from RTG unit.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_default_output, line):
            ctrl = self._regex_helper.search(self._re_default_output, line).group('CTRL')
            ip = self._regex_helper.search(self._re_default_output, line).group('IP')
            out = self._regex_helper.search(self._re_default_output, line).group('OUT')
            self.current_ret[ctrl] = {'IP': ip, self._key_dict[self.usage]: out}
            raise ParsingDone

    # Example line: CTRL-01 10.0.2.11          FRAME_SYNC  |    UNSYNC     |
    _re_link = re.compile(r'(?P<CTRL>CTRL-\d+)\s*(?P<IP>\d+\.\d+\.\d+\.\d+)\s*(?P<LINK1>\w+)\s*\|\s*(?P<LINK2>\w+)')

    def _parse_link(self, line):
        """
        Parse line with aiftool links statuses of RTG unit.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_link, line):
            ctrl = self._regex_helper.search(self._re_link, line).group('CTRL')
            ip = self._regex_helper.search(self._re_link, line).group('IP')
            link1 = self._regex_helper.search(self._re_link, line).group('LINK1')
            link2 = self._regex_helper.search(self._re_link, line).group('LINK2')
            self.current_ret[ctrl] = {'IP': ip, 'LINK_1': link1, 'LINK_2': link2}
            raise ParsingDone

    # Example line: CTRL-01 10.0.2.11       run=RTG_RL15.0_BLD-77(fs2)  fs1=RTG_RL15.0_BLD-72  fs2=RTG_RL15.0_BLD-77
    _re_ver = re.compile(r'(?P<CTRL>CTRL-\d+)\s*(?P<IP>\d+\.\d+\.\d+\.\d+)\s*'
                         r'run=(?P<RUN>\S*)\((?P<ACTIVE>\w+)\)\s*fs1=(?P<FS1>\S*)\s*fs2=(?P<FS2>[^\s]*)\s*(OK)?')

    def _parse_ver(self, line):
        """
        Parse line with software versions on RTG unit.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_ver, line):
            ctrl = self._regex_helper.search(self._re_ver, line).group('CTRL')
            ip = self._regex_helper.search(self._re_ver, line).group('IP')
            run = self._regex_helper.search(self._re_ver, line).group('RUN')
            fs1 = self._regex_helper.search(self._re_ver, line).group('FS1')
            fs2 = self._regex_helper.search(self._re_ver, line).group('FS2')
            active = self._regex_helper.search(self._re_ver, line).group('ACTIVE')
            self.current_ret[ctrl] = {'IP': ip, 'RUN': run, 'FS_1': fs1, 'FS_2': fs2, 'ACTIVE': active}
            raise ParsingDone

    # Example line: CTRL-01 10.0.2.11       CORE-1    Average CPU load:   1.60% (Min:   1.60% Max:   1.62%)
    _re_cpu = re.compile(r'(?P<CTRL>CTRL-\d+)\s*(?P<IP>\d+\.\d+\.\d+\.\d+)\s*(?P<CORE>CORE-\d)\s*Average CPU.? load:\s*'
                         r'(?P<AVERAGE>\d+.\d+%)\s*\(Min:\s*(?P<MIN>\d+.\d+%)\s*Max:\s*(?P<MAX>\d+.\d+%)\)')

    def _parse_cpu(self, line):
        """
        Parse line with cpu load from RTG unit.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_cpu, line):
            ctrl = self._regex_helper.search(self._re_cpu, line).group('CTRL')
            ip = self._regex_helper.search(self._re_cpu, line).group('IP')
            core = self._regex_helper.search(self._re_cpu, line).group('CORE')
            average = self._regex_helper.search(self._re_cpu, line).group('AVERAGE')
            min_load = self._regex_helper.search(self._re_cpu, line).group('MIN')
            max_load = self._regex_helper.search(self._re_cpu, line).group('MAX')
            self.current_ret.setdefault(ctrl, {})['IP'] = ip
            self.current_ret[ctrl][core] = {'AVERAGE': average, 'MIN': min_load, 'MAX': max_load}
            raise ParsingDone

    # Example line: CTRL-01: time
    _re_mmi_output = re.compile(r'(?P<CTRL>CTRL-\d+):\s*(?P<OUT>.*)')

    def _parse_mmi_output(self, line):
        """
        Parse line with output from mmi command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_mmi_output, line):
            ctrl = self._regex_helper.search(self._re_mmi_output, line).group('CTRL')
            out = self._regex_helper.search(self._re_mmi_output, line).group('OUT')
            if self.current_ret.get(ctrl) is None:
                self.current_ret.setdefault(ctrl, {})['MMI_COMMAND_OUTPUT'] = ""
            self.current_ret[ctrl]['MMI_COMMAND_OUTPUT'] = f"{self.current_ret[ctrl]['MMI_COMMAND_OUTPUT']}{out}\n"
            raise ParsingDone

    # Example line: Recover not need. Directory /rom/config/rtg exist
    _re_recover = re.compile(r'(?P<RECOVER>Recover not need\. Directory /rom/config/rtg exist|'
                             r'Copying config complete\. Recover passed)')

    def _parse_recover(self, line):
        """
        Parse line with success recover status.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_recover, line):
            recover_status = self._regex_helper.search(self._re_recover, line).group('RECOVER')
            self.current_ret.setdefault('RECOVER_STATUS', []).append(recover_status)
            raise ParsingDone

    # Example line: CTRL-01 10.0.2.11       L2-FR [0x240130]A:0x1fff/I:3 [0x240134]A:0x1fff/I:3 [0x240138]A:0x0000/I:0
    #               [0x24013c]A:0x0000/I:0 L2-DE [0x24011c]A:0x1fff/I:3 [0x240120]A:0x1fff/I:3 [0x240124]A:0x0000/I:0
    #               [0x240128]A:0x0000/I:0
    _re_parse_fpga_registers = re.compile(r'(?P<CTRL>CTRL-\d+)\s*(?P<IP>\d+\.\d+\.\d+\.\d+)\s*'
                                          r'(?P<FR>L[12]-FR)\s*(?P<FRAMER>.*\s*)\s*(?P<DE>L[12]-DE)(?P<DEFRAMER>.*\s*)')

    def _parse_fpga_registers(self, line):
        """
        Parse line with FPGA framer/deframer registers.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_parse_fpga_registers, line):
            ctrl = self._regex_helper.search(self._re_parse_fpga_registers, line).group('CTRL')
            ip = self._regex_helper.search(self._re_parse_fpga_registers, line).group('IP')
            fr_key = self._regex_helper.search(self._re_parse_fpga_registers, line).group('FR')
            fr_registers = self._regex_helper.search(self._re_parse_fpga_registers, line).group('FRAMER').split()
            de_key = self._regex_helper.search(self._re_parse_fpga_registers, line).group('DE')
            de_registers = self._regex_helper.search(self._re_parse_fpga_registers, line).group('DEFRAMER').split()
            self.current_ret[ctrl] = {'IP': ip, fr_key: fr_registers, de_key: de_registers}
            raise ParsingDone

    def _parse_get_parameter(self, line):
        """
        Parse line with parameter.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_prompt, line) is None:
            self.current_ret.setdefault('PARAMS', []).append(line)
            raise ParsingDone


